<?php
declare(strict_types=1);
/** Portable HTML, with all local media embedded (or linked within the accompanying ZIP). */
function offline_export_html(string $json):string {
 $page=<<<'HTML'
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sector Sign · Presentación offline</title>
<style>html,body{margin:0;height:100%;overflow:hidden;background:#020713;color:#fff;font-family:system-ui,Arial}#screen{position:fixed;inset:0}#screen img,#screen video{width:100%;height:100%;object-fit:contain}#info{position:fixed;left:16px;bottom:12px;color:#b4caff;font-size:12px}#caption{position:fixed;left:0;right:0;bottom:60px;background:#000b;text-align:center;color:white;font-size:clamp(16px,2.5vw,30px);padding:10px;max-height:30vh;overflow:hidden}#panel{position:fixed;top:14px;right:14px;display:flex;flex-wrap:wrap;gap:9px;z-index:10}button{border:1px solid #ffffff40;background:#174b96;color:#fff;border-radius:9px;padding:9px 15px;font:600 13px system-ui;cursor:pointer}#note{position:fixed;top:14px;left:14px;color:#d5e9ff;font-size:12px;max-width:50%;background:#0e2036aa;padding:8px;border-radius:7px}</style></head>
<body><div id="screen"></div><div id="caption"></div><div id="note">Pulsa 🔊 para activar voz y música. El idioma y la voz deben estar instalados en este equipo.</div><div id="panel"><button id="sound">🔇 Sonido</button><button id="restart">↻ Inicio</button><button id="full">⛶ Pantalla completa</button></div><div id="info">SECTOR SIGN · OFFLINE</div>
<script>const manifest=__SECTOR_SIGN_DATA__;let i=0,timer,muted=true,clip=null,music=null,voice=null;
const byId=id=>document.getElementById(id);const all=manifest.items||[];
function scheduled(sc){if(!sc||!Object.keys(sc).length)return true;const parts={};new Intl.DateTimeFormat('en-US',{timeZone:manifest.timezone||'America/Lima',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hour12:false,weekday:'short'}).formatToParts(new Date()).forEach(p=>{if(p.type!=='literal')parts[p.type]=p.value});const ymd=parts.year+'-'+parts.month+'-'+parts.day,m=(Number(parts.hour)%24)*60+Number(parts.minute),days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];const toM=x=>Number(x.slice(0,2))*60+Number(x.slice(3)),start=sc.start?toM(sc.start):0,end=sc.end?toM(sc.end):1440;let wd=days.indexOf(parts.weekday),valid,effectiveDate=ymd;if(sc.start&&sc.end&&start>end){valid=m>=start||m<end;if(m<end){wd=(wd+6)%7;const prev=new Date(ymd+'T12:00:00Z');prev.setUTCDate(prev.getUTCDate()-1);effectiveDate=prev.toISOString().slice(0,10);}}else valid=start===end?true:m>=start&&m<end;return valid&&!(sc.from&&effectiveDate<sc.from||sc.until&&effectiveDate>sc.until)&&(!sc.days?.length||sc.days.includes(wd));}
function cancelVoice(){try{speechSynthesis.cancel();}catch{}}
function stopClip(){if(clip){clip.pause();clip.src='';clip=null;}cancelVoice();}
function setupMusic(){const m=manifest.soundtrack||{},id=m.media_id||'',src=manifest.assets[id];if(!src){if(music){music.pause();music=null;}return;}if(!music){music=new Audio(src);music.loop=true;music.play().catch(()=>{});}music.volume=Math.max(0,Math.min(1,(m.volume??35)/100));music.muted=muted;}
function announce(a){const v=a?.voice;if(!v?.enabled||!v.text||muted)return;if('speechSynthesis'in window){try{voice=new SpeechSynthesisUtterance(v.text);voice.lang=v.lang||'es-PE';voice.rate=v.rate||1;speechSynthesis.speak(voice);}catch{}}}
function next(){clearTimeout(timer);stopClip();setupMusic();const items=all.filter(x=>scheduled(x.schedule));if(!items.length){byId('screen').textContent='Sin anuncios para este horario';timer=setTimeout(next,60000);return;}const x=items[i++%items.length],src=manifest.assets[x.id];if(!src){timer=setTimeout(next,1000);return;}byId('screen').replaceChildren();const v=x.mime?.startsWith('video/');const node=document.createElement(v?'video':'img');node.src=src;node.style.objectFit=x.fit||'contain';if(v){node.autoplay=true;node.loop=true;node.playsInline=true;node.muted=muted||x.audio?.mode==='replace';node.play().catch(()=>{});}byId('screen').appendChild(node);byId('caption').textContent=x.audio?.voice?.enabled&&x.audio.voice.caption!==false?x.audio.voice.text||'':'';const a=x.audio||{};if(a.media_id&&manifest.assets[a.media_id]){clip=new Audio(manifest.assets[a.media_id]);clip.volume=Math.max(0,Math.min(1,(a.volume??85)/100));clip.muted=muted;clip.play().catch(()=>{});}if(music)music.volume=Math.max(0,Math.min(1,(manifest.soundtrack?.volume??35)/100))*(x.audio?.voice?.enabled?0.35:1);announce(a);timer=setTimeout(next,Math.max(2,x.duration||8)*1000);}
byId('sound').onclick=()=>{muted=!muted;byId('sound').textContent=muted?'🔇 Sonido':'🔊 Sonido';if(music){music.muted=muted;if(!muted)music.play().catch(()=>{});}if(clip){clip.muted=muted;if(!muted)clip.play().catch(()=>{});}document.querySelector('video')&&(document.querySelector('video').muted=muted);if(muted)cancelVoice();};
byId('restart').onclick=()=>{i=0;next();};byId('full').onclick=()=>document.documentElement.requestFullscreen?.();
next();
</script></body></html>
HTML;
 return str_replace('__SECTOR_SIGN_DATA__',$json,$page);
}
